print("拟合的多项式为：")
print(poly_func)

# 绘制原始数据和拟合曲线
x_fit = np.linspace(min(x), max(x), 100)
y_fit = poly_func(x_fit)

plt.scatter(x, y, color='red', label='Original Data',marker='o',s=30,alpha=0.2)
plt.plot(x_fit, y_fit, label=f'Fitted Polynomial (degree={degree})')
plt.legend()
plt.xlabel('x')
plt.ylabel('y')
plt.title('SDF Fit')
plt.show()